1	import copy from "copy-to-clipboard";
2	import { ExternalLinkIcon, LayoutListIcon, MapIcon } from "lucide-react";
3	import { lazy, Suspense } from "react";
4	import { toast } from "react-hot-toast";
5	import { useParams, useSearchParams } from "react-router-dom";
6	import MemoView from "@/components/MemoView";
7	import PagedMemoList, { getMemoKey } from "@/components/PagedMemoList";
8	import UserAvatar from "@/components/UserAvatar";
9	import { Button } from "@/components/ui/button";
10	import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
11	import { useMemoFilters, useMemoSorting } from "@/hooks";
12	import { useUser } from "@/hooks/useUserQueries";
13	import { State } from "@/types/proto/api/v1/common_pb";
14	import { Memo } from "@/types/proto/api/v1/memo_service_pb";
15	import { useTranslate } from "@/utils/i18n";
16	
17	type TabView = "memos" | "map";
18	
19	const UserMemoMap = lazy(() => import("@/components/UserMemoMap"));
20	
21	interface User {
22	  name: string;
23	  username: string;
24	  displayName: string;
25	  avatarUrl?: string;
26	  description?: string;
27	}
28	
29	const ProfileHeader = ({ user, onCopyProfileLink, shareLabel }: { user: User; onCopyProfileLink: () => void; shareLabel: string }) => (
30	  <div className="border-b border-border/10 px-4 py-8 sm:px-6">
31	    <div className="mx-auto flex max-w-2xl gap-4 sm:gap-6">
32	      <UserAvatar className="h-20 w-20 shrink-0 rounded-2xl shadow-sm sm:h-24 sm:w-24" avatarUrl={user.avatarUrl} />
33	      <div className="flex flex-1 flex-col gap-3">
34	        <div>
35	          <h1 className="text-2xl font-bold text-foreground sm:text-3xl">{user.displayName || user.username}</h1>
36	          {user.displayName && <p className="text-sm text-muted-foreground">@{user.username}</p>}
37	        </div>
38	        {user.description && <p className="text-sm text-foreground/70">{user.description}</p>}
39	        <Button variant="outline" size="sm" onClick={onCopyProfileLink} className="w-fit gap-2">
40	          <ExternalLinkIcon className="h-4 w-4" />
41	          {shareLabel}
42	        </Button>
43	      </div>
44	    </div>
45	  </div>
46	);
47	
48	const UserProfile = () => {
49	  const t = useTranslate();
50	  const username = useParams().username;
51	  const [searchParams, setSearchParams] = useSearchParams();
52	  const activeTab = (searchParams.get("view") === "map" ? "map" : "memos") as TabView;
53	
54	  const { data: user, isLoading, error } = useUser(`users/${username}`, { enabled: !!username });
55	
56	  if (error && !isLoading) {
57	    toast.error(t("message.user-not-found"));
58	  }
59	
60	  const memoFilter = useMemoFilters({
61	    creatorName: user?.name,
62	    includeShortcuts: false,
63	    includePinned: true,
64	  });
65	
66	  const { listSort, orderBy } = useMemoSorting({
67	    pinnedFirst: true,
68	    state: State.NORMAL,
69	  });
70	
71	  const handleCopyProfileLink = () => {
72	    if (!user) return;
73	    copy(`${window.location.origin}/u/${encodeURIComponent(user.username)}`);
74	    toast.success(t("message.copied"));
75	  };
76	
77	  const toggleTab = (view: TabView) => {
78	    setSearchParams((prev) => {
79	      view === "map" ? prev.set("view", "map") : prev.delete("view");
80	      return prev;
81	    });
82	  };
83	
84	  if (isLoading) return null;
85	
86	  return (
87	    <section className="flex min-h-screen w-full flex-col bg-background">
88	      {user ? (
89	        <>
90	          <ProfileHeader user={user} onCopyProfileLink={handleCopyProfileLink} shareLabel={t("common.share")} />
91	
92	          <div className="border-b border-border/10 mb-4">
93	            <div className="mx-auto flex max-w-2xl">
94	              <Tabs value={activeTab} onValueChange={(value) => toggleTab(value as TabView)} variant="underline">
95	                <TabsList>
96	                  <TabsTrigger value="memos">
97	                    <LayoutListIcon className="h-4 w-4" />
98	                    {t("common.memos")}
99	                  </TabsTrigger>
100	                  <TabsTrigger value="map">
101	                    <MapIcon className="h-4 w-4" />
102	                    {t("common.map")}
103	                  </TabsTrigger>
104	                </TabsList>
105	              </Tabs>
106	            </div>
107	          </div>
108	
109	          <div className="flex-1">
110	            <div className="mx-auto w-full max-w-2xl">
111	              {activeTab === "memos" ? (
